<script setup>
import{ref}from'vue';const selected=ref(null),names=['Bremsstrahlung','Non-resonant','Resonant'],rows=[[.000850,.000111,.000142],[.0389,1.74,.114],[.00156,.0870,.601]],produced=[.00137,1.96,.705];const fmt=n=>n.toPrecision(3);const share=(r,c)=>100*rows[r][c]/rows.reduce((s,row)=>s+row[c],0)
</script><template><div class="matrix-layout"><div class="matrix"><span/><b v-for="c in 3">SR{{c}}</b><template v-for="(row,r) in rows"><strong>{{names[r]}}</strong><button v-for="(n,c) in row" :style="{background:`rgba(119,201,255,${.08+.68*Math.sqrt(n/1.74)})`}" @mouseenter="selected={r,c,n}" @focus="selected={r,c,n}" @mouseleave="selected=null" @blur="selected=null"><span>{{fmt(n)}}</span><small>{{share(r,c).toFixed(share(r,c)&lt;.1?3:1)}}% of SR{{c+1}}</small></button></template><strong>Total</strong><b v-for="n in [.0413,1.82,.715]" class="total">{{n}}</b></div><aside><div class="eyebrow">Production → observation</div><h2>{{selected?names[selected.r]+' → SR'+(selected.c+1):'Annihilation dominates at 90 MeV'}}</h2><p v-if="selected"><strong>{{fmt(selected.n)}}</strong> selected events<br/>from {{produced[selected.r]}} produced.<br/><span style="font-size:14px">{{share(selected.r,selected.c).toFixed(2)}}% of this region’s signal.</span></p><p v-else>Cell values: expected selected events.<br/>Percentages: composition within each SR.</p><p class="small muted">Non-resonant: ≈95% of SR2.<br/>Resonant: ≈84% of SR3.<br/>Bremsstrahlung is negligible here.</p></aside></div></template><style scoped>.matrix-layout{display:grid;grid-template-columns:2fr 1fr;gap:38px;margin-top:22px}.matrix{align-self:start;grid-template-rows:24px repeat(3,76px) 30px;display:grid;grid-template-columns:145px repeat(3,1fr);gap:5px;align-items:center}.matrix>b{text-align:center;font-size:16px}.matrix>strong{font-size:15px;font-weight:500}.matrix button{height:76px;border:1px solid #ffffff20;border-radius:3px;color:#edf1f7;cursor:pointer;transition:all .3s}.matrix button:hover,.matrix button:focus{outline:2px solid #f0c36e;transform:translateY(-2px)}button span{font-size:23px;display:block}button small{font-size:10px;opacity:.7}.total{padding-top:12px;color:#f0c36e}aside{border-left:1px solid #ffffff25;padding-left:25px;padding-top:8px}aside p{font-size:15px;line-height:1.45}aside h2{font-size:18px}aside strong{font-size:32px;color:#f0c36e}</style>
